export function selectVideoStoryFamily(concept={}){
 const id=String(concept.topicId||"").toLowerCase();
 const goal=String(concept.goal||"").toLowerCase();
 const cat=String(concept.categoryId||"");
 // Everyday fatigue, bodily regulation and calm presence must not default to
 // ambition/achievement films merely because they share Energy & Confidence.
 // This is an editorial routing choice, never a diagnosis or trauma inference.
 if(/^(?:everyday-overload|evening-fatigue|mental-tiredness|recovery-after-load|low-energy|mental-clarity|body-awareness|breathing-practices|muscle-relaxation|calm-presence)$/.test(id))return "stress";
 if(/^(?:motivation-drive|morning-energy|low-self-esteem|self-acceptance|healthy-habits)$/.test(id))return "growth";
 if(/personal-growth|self-confidence|procrastin|follow-through|self-discipline|learning|finding-self|perfection/.test(id))return "growth";
 if(/income|money|financial|career|entrepreneur|business|price|leadership|work/.test(id))return "money";
 if(/stress|anxiet|panic|burnout|fatigue|worry|trauma|mood|apathy/.test(id))return "stress";
 if(/purpose|life-transition|decision|meaning|goal-setting|values/.test(id))return "purpose";
 if(/intimacy|dating|communication|couple|partner|love|family|loneliness|relationship|trust|rejection/.test(id))return "intimacy";
 if(/growth|саморазвит|desarrollo personal|личност|развити/.test(goal))return "growth";
 if(/income|money|salary|business|доход|деньг|dinero/.test(goal))return "money";
 if(/stress|relief|anxiety|стресс|тревог|ansiedad|estrés/.test(goal))return "stress";
 if(/purpose|смысл|предназнач|sentido de la vida/.test(goal))return "purpose";
 if(/relationship|love|любов|отношени|amor|relación/.test(goal))return "intimacy";
 if(cat==="love-relationships")return "intimacy";
 if(cat==="stress-anxiety")return "stress";
 if(cat==="energy-confidence")return "growth";
 if(cat==="goals-money")return "purpose";
 return "generic";
}
export function listAuthoredFilmPlots(family){
 return G[family]||G.generic;
}
